<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class ProposalFile extends Model { protected $fillable=['proposal_id','uploaded_by','name','path','mime_type','size']; public function proposal():BelongsTo{return $this->belongsTo(Proposal::class)->withTrashed();} public function uploader():BelongsTo{return $this->belongsTo(User::class,'uploaded_by')->withTrashed();} }